/* Auth block layout. Visuals come from AuthLayout, AuthCard and the tokens. */

.frame {
  width: 100%;
  height: 100%;
}

.mark {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
  letter-spacing: var(--tracking-display);
  color: inherit;
}

.glyph {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: var(--r-sm);
  background: var(--brand-gradient);
  box-shadow: var(--glow-sm);
  font-size: 14px;
  color: var(--ink-inverse);
}

.help {
  font-size: var(--text-small);
  font-weight: 700;
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.otp {
  display: flex;
  justify-content: center;
}

.alt {
  font-size: var(--text-small);
  color: var(--ink-muted);
  text-align: center;
}

.link {
  padding: 0;
  border: 0;
  background: none;
  font-weight: 700;
  color: var(--ink-brand);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.link:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: var(--r-2xs);
}

.setup {
  display: grid;
  grid-template-columns: 148px minmax(0, 1fr);
  gap: 18px;
  align-items: center;
}

@media (max-width: 480px) {
  .setup {
    grid-template-columns: minmax(0, 1fr);
    justify-items: center;
  }
}

.qr {
  display: block;
  width: 148px;
  height: 148px;
  border-radius: var(--r-md);
  box-shadow: inset 0 0 0 1px var(--line);
}

.steps {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: var(--text-small);
  color: var(--ink-body);
}

.secret {
  align-self: flex-start;
  padding: 6px 10px;
  border-radius: var(--r-sm);
  background: var(--surface-sunken);
  box-shadow: inset 0 0 0 1px var(--line);
  font-family: var(--font-mono);
  font-size: 13px;
  letter-spacing: 0.08em;
  color: var(--ink-heading);
}

.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

@media (max-width: 480px) {
  .row {
    grid-template-columns: minmax(0, 1fr);
  }
}

.between {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

"use client";

import { AuthCard, AuthLayout } from "@/components/shell/AuthCard";
import { Button } from "@/components/ui/Button/Button";
import { Checkbox } from "@/components/ui/Checkbox/Checkbox";
import { Field } from "@/components/ui/Field/Field";
import { IconShield, IconUser } from "@/components/ui/Icon/Icon";
import { TextInput } from "@/components/ui/TextInput/TextInput";
import styles from "./Auth.module.css";

export type AuthSignupProps = {
  /** Fill the parent instead of the viewport. */
  contained?: boolean;
};

/** Create an account: name, work email, a password and the terms. Drop it at app/signup. */
export default function AuthSignup({ contained }: AuthSignupProps) {
  return (
    <div className={contained ? styles.frame : undefined}>
      <AuthLayout
        contained={contained}
        header={
          <>
            <span className={styles.mark}>
              <span className={styles.glyph} aria-hidden="true">
                A
              </span>
              Acme
            </span>
            <a className={styles.help} href="#login">
              Sign in
            </a>
          </>
        }
        footer={
          <>
            <IconShield size={14} />
            You will set up multi-factor authentication after creating your account.
          </>
        }
      >
        <AuthCard width="md" icon={<IconUser size={22} />} title="Create your account" subtitle="Start a free workspace for your team. No card needed.">
          <form onSubmit={(e) => e.preventDefault()} style={{ display: "contents" }}>
            <div className={styles.row}>
              <Field label="First name">
                <TextInput autoComplete="given-name" placeholder="Jane" />
              </Field>
              <Field label="Last name">
                <TextInput autoComplete="family-name" placeholder="Cooper" />
              </Field>
            </div>
            <Field label="Work email">
              <TextInput type="email" autoComplete="email" placeholder="jane@acme.example" />
            </Field>
            <Field label="Password" hint="At least 12 characters.">
              <TextInput type="password" revealable autoComplete="new-password" />
            </Field>
            <Checkbox label="I accept the terms and the privacy policy" />
            <Button type="submit" size="lg" fullWidth>
              Create account
            </Button>
            <p className={styles.alt}>
              Already have an account?{" "}
              <a className={styles.link} href="#login">
                Sign in
              </a>
            </p>
          </form>
        </AuthCard>
      </AuthLayout>
    </div>
  );
}

import AuthSignup from "@/components/blocks/auth-signup";

export default function Page() {
  return <AuthSignup />;
}
